function filtered() { return state.reservations.filter(r => (view === 'week' || dayKey(r.start) === selectedDate) && (!category || r.category === category) && (!search || [person(r.person)?.name, person(r.student)?.name, person(r.student)?.registration].join(' ').toLowerCase().includes(search.toLowerCase()))); }
