function finance() { const paid = (state.payments || []).reduce((a, p) => a + p.amount, 0); const refunded = (state.refunds || []).filter(r => r.status === 'processed').reduce((a, p) => a + p.amount, 0); return heading('CONTROLE MANUAL', 'Financeiro, com clareza.', 'Conferência de Pix e registro de devoluções. Nenhuma movimentação bancária.', '<button id="export">↓ Exportar dados</button>') + `<div class="stats"><div class="stat featured"><div class="stat-label">Recebimentos registrados</div><div class="stat-value">${money(paid)}</div><small>Conferência manual, dados fictícios</small></div><div class="stat"><div class="stat-label">Devoluções registradas</div><div class="stat-value">${money(refunded)}</div><small>Somente devoluções efetivadas</small></div><div class="stat"><div class="stat-label">Reembolsos pendentes</div><div class="stat-value">${money((state.refunds || []).filter(r => r.status !== 'processed').reduce((a, r) => a + r.amount, 0))}</div><small>Exigem devolução fora do sistema</small></div><div class="stat"><div class="stat-label">Reservas aguardando</div><div class="stat-value">${state.reservations.filter(r => r.status === 'awaiting_payment').length}</div><small>Validade: ${state.unit.settings.hold_minutes} minutos</small></div></div><div class="notice amber"><b>Pix manual · modo demonstração</b><br>${esc(state.unit.settings.pix_label)}. Ler um QR ou receber um comprovante não confirma o pagamento. Não faça transferências para testar.</div><div class="card"><div class="card-head"><h2>Reservas externas</h2></div>${rowsHtml(state.reservations.filter(r => r.category === 'external'))}</div><div class="card"><div class="card-head"><h2>Devoluções e retenções</h2></div>${state.refunds?.length ? `<div class="table-wrap"><table><thead><tr><th>Reserva</th><th>Retido</th><th>A devolver</th><th>Situação</th><th></th></tr></thead><tbody>${state.refunds.map(r => `<tr><td>#${r.reservation}</td><td>${money(r.retained)}</td><td>${money(r.amount)}</td><td>${badge(r.status)}</td><td>${r.status !== 'processed' && can('admin', 'reception') ? `<button data-refund="${r.id}" class="text-link">Registrar devolução ↗</button>` : esc(r.reference || '')}</td></tr>`).join('')}</tbody></table></div>` : empty('Nenhum reembolso neste momento.')}</div>`; }
function settings() { const s = state.unit.settings; return heading('PARAMETRIZAÇÃO VERSIONADA', 'Uma operação do seu jeito.', 'As alterações preservam os termos das reservas já criadas.') + `<div class="notice amber">Configuração fictícia. Âncora: <b>${esc(s.anchor)}</b> (${s.anchor_confirmed ? 'confirmada' : 'aguarda confirmação'}). Prazo de uso profissional: <b>${s.use_deadline_minutes === null ? 'pendente' : s.use_deadline_minutes + ' min após término'}</b>. Tutoria de reservas: ${s.supervision_confirmed ? 'confirmada' : 'pendente'}.</div><div class="grid-main"><div class="card"><div class="card-head"><h2>Oferta e políticas • versão ${state.unit.version}</h2><div class="row"><button id="add-room">＋ Sala</button><button id="edit-settings" class="primary">Editar configurações</button></div></div><div class="card-body"><div class="detail-list"><div><span>Aluno / interno / externo</span>${s.student_duration} / ${s.internal_duration} / ${s.external_duration} minutos</div><div><span>Aluguel externo / retenção</span>${money(s.external_price)} / ${s.retention}%</div><div><span>Compartilhamento para internos</span>${s.internal_sharing === 'shared' ? 'Quando houver intervalo livre' : 'Exclusivo para alunos'}</div><div><span>Externos em dias úteis</span>${s.external_weekdays ? 'Liberados' : 'Bloqueados'}</div><div><span>Oferta diária por sala</span>${s.daily_offer} / capacidade ${state.capacity.theoretical}</div><div><span>Tempo de reserva temporária</span>${s.hold_minutes} minutos</div></div><h3 style="margin-top:28px">Prévia dos inícios ofertados</h3><div class="row">${state.capacity.starts.map((t) => `<span class="pill">${t}</span>`).join('')}</div><p class="description" style="margin-top:16px">${state.capacity.weekly} vagas por semana, segunda a quinta, antes de feriados, jornadas e reservas. Salvar oferta não cria reservas. A elegibilidade final é revalidada na confirmação.</p></div></div><aside><div class="card"><div class="card-head"><h2>Justificativas de atraso</h2><button class="text-link" id="add-reason">＋</button></div><div class="card-body">${state.reasons.map(r => `<div class="activity">${esc(r.title)}<br><small>${r.active ? 'Ativo' : 'Inativo'}</small> <button class="text-link" data-reason="${r.id}">Editar</button></div>`).join('')}</div></div><div class="card"><div class="card-head"><h2>Segurança & dados</h2></div><div class="card-body"><p class="description">Backup SQLite consistente por comando. Consulte o guia para restauração e retenção.</p><button id="export" style="margin-top:16px">↓ Exportar esta unidade</button></div></div></aside></div>`; }
function schedulesPage() { const scales = scheduleData?.schedules || []; return heading('EQUIPE & COBERTURA', 'Escalas que respeitam a rotina.', 'Ciclos contínuos de 84 dias. Publicação condicionada à validação.', can('admin') ? '<button id="add-work">Cadastrar jornada</button><button id="generate-schedule" class="primary">＋ Gerar proposta</button>' : '') + `<div class="notice">${can('admin') ? 'A proposta considera o ciclo completo e as fronteiras de descanso. Rascunhos podem ter pendências; nenhuma pendência pode ser ignorada ao publicar.' : 'A equipe visualiza somente o mês vigente. O motor considera o ciclo completo para validar descanso e continuidade.'} Âncora: <b>${esc(state.unit.settings.anchor)}</b>.</div>${scales.length ? scales.map((sc) => `<div class="card"><div class="card-head"><div><h2>Versão ${sc.version} • ciclo a partir de ${dateFormat(sc.anchor)}</h2><small>Registro #${sc.id} · ${sc.assignments.filter((a) => !a.off && !a.adjustment).length} plantões ${badge(sc.status)}</small></div>${can('admin') && sc.status === 'draft' ? `<div class="row"><button data-edit-schedule="${sc.id}">Revisar alocações</button><button class="primary" data-publish="${sc.id}">Publicar</button></div>` : ''}</div>${sc.errors.length ? `<div class="card-body"><div class="notice amber"><b>${sc.errors.length} pendências impedem publicação</b><br>${sc.errors.slice(0, 12).map(esc).join('<br>')}${sc.errors.length > 12 ? '<br>Veja todas em Revisar alocações.' : ''}</div></div>` : ''}<div class="table-wrap"><table><thead><tr><th>Data / ciclo</th><th>Plantão</th><th>Profissional</th><th>Horário</th></tr></thead><tbody>${sc.assignments.slice(0, can('admin') ? 200 : 1000).map((a) => `<tr><td>${dateFormat(a.date, { weekday: 'short', day: '2-digit', month: '2-digit' })}<small>${a.cycle ? 'Ciclo ' + a.cycle.cycle + ' · Semana ' + a.cycle.week : 'Pré-ciclo'}</small></td><td>${esc(a.slot)}</td><td>${esc(person(a.person)?.name)}</td><td>${a.off ? 'Folga explícita' : `${esc(a.start)} — ${esc(a.end)}`}${a.adjustment ? '<small>Ajuste para abertura de sábado</small>' : ''}</td></tr>`).join('')}</tbody></table></div></div>`).join('') : '<div class="card">' + empty('Ainda não há escala publicada para sua unidade.<br>O administrador pode gerar e revisar uma proposta.') + '</div>'}`; }
function swapsPage() { return heading('TRABALHO EM EQUIPE', 'Permutas com rastreabilidade.', 'Colega aceita; administrador valida e publica. Sem integração com registro de ponto.', can('teacher', 'intern') ? '<button id="request-swap" class="primary">＋ Solicitar permuta</button>' : '') + `<div class="card">${scheduleData?.swaps?.length ? `<div class="table-wrap"><table><thead><tr><th>Solicitante</th><th>Colega</th><th>Motivo</th><th>Situação</th><th></th></tr></thead><tbody>${scheduleData.swaps.map((sw) => `<tr><td>${esc(person(sw.source)?.name)}</td><td>${esc(person(sw.target)?.name)}</td><td>${esc(sw.reason)}</td><td>${badge(sw.status)}</td><td>${sw.target === session.user.person && sw.status === 'requested' ? `<button data-swap-accept="${sw.id}">Aceitar</button>` : ''}${can('admin') && sw.status === 'accepted' ? `<button class="primary" data-swap-approve="${sw.id}">Validar e aprovar</button>` : ''}</td></tr>`).join('')}</tbody></table></div>` : empty('Nenhuma permuta solicitada.')}</div><div class="notice amber">O tratamento do ponto segue orientação validada pela gestão/RH. O sistema registra o trabalho efetivo e não simula batidas no Myaghora.</div>`; }
function auditPage() { return heading('HISTÓRICO DA UNIDADE', 'Cada decisão deixa um registro.', 'Eventos administrativos, financeiros e operacionais com autor e horário.') + `<div class="card"><div class="table-wrap"><table><thead><tr><th>Data e hora</th><th>Autor</th><th>Evento</th><th>Entidade</th><th>Detalhes</th></tr></thead><tbody>${state.audit?.map(a => `<tr><td>${dateFormat(a.created)} ${timeFormat(a.created)}</td><td>${a.actor === 0 ? 'Tarefa do servidor' : 'Usuário #' + a.actor}</td><td>${esc(a.action)}</td><td>${esc(a.entity)}</td><td><button class="text-link" data-audit="${a.id}">Ver registro</button></td></tr>`).join('')}</tbody></table></div></div>`; }
function account() { return heading('ACESSO INDIVIDUAL', 'Minha conta', 'Defina sua senha no próprio sistema e acompanhe seus impedimentos.') + `<div class="grid-main"><div class="card"><div class="card-head"><h2>${esc(person(session.user.person)?.name || session.user.login)}</h2>${badge(labels[session.user.role])}</div><div class="card-body">${session.temporary ? '<div class="notice amber">Modo de implantação: senha ainda não definida. Ao salvar uma senha, todas as sessões temporárias serão encerradas.</div>' : ''}<form id="password-form"><div class="form-grid">${!session.temporary ? field('Senha atual', input('current', 'password', '', 'required autocomplete="current-password"'), true) : ''}${field('Nova senha', input('password', 'password', '', 'minlength="10" required autocomplete="new-password"'))}${field('Confirmar senha', input('confirmation', 'password', '', 'minlength="10" required autocomplete="new-password"'))}</div>${actions(session.temporary ? 'Definir senha' : 'Alterar senha')}<div class="inline-error" role="alert"></div></form></div></div><div class="card"><div class="card-head"><h2>Penalidades</h2></div><div class="card-body">${state.penalties.length ? state.penalties.map(p => `<div class="activity">${esc(p.reason)}<br><small>Reserva #${p.reservation} · Até ${dateFormat(p.end)} ${timeFormat(p.end)}<br>${new Date(p.end) > new Date() ? 'Bloqueio ativo para novas reservas' : 'Encerrada'}</small></div>`).join('') : '<p class="description">Nenhuma penalidade registrada.</p>'}</div></div></div>`; }
function booking() {
    const reception = can('reception');
    const s = state.unit.settings;
    dialog('Nova reserva', `<div class="form-grid">${field('Categoria', `<select name="category" id="book-category">${(reception ? ['student', 'external', 'internal'] : ['internal']).map(c => `<option value="${c}">${labels[c]}</option>`).join('')}</select>`)}${field('Sala', `<select name="room">${options(state.rooms)}</select>`)}${field('Profissional responsável', `<select name="person" id="book-person"></select>`)}<div id="student-field">${field('Aluno Platinum', `<select name="student">${options(state.people.filter(p => p.kind === 'student'))}</select>`)}</div>${field('Data', input('date', 'date', selectedDate, 'required'))}${field('Início', input('time', 'time', '08:00', 'step="600" required'))}</div><div id="booking-terms" class="notice" style="margin-top:20px"></div><div id="accept-policy"></div><button id="check-availability" type="button">Consultar disponibilidade</button><div id="availability-result" class="description"></div>${actions('Revalidar e confirmar')}`, async (f) => { const cat = value(f, 'category'); const body = { category: cat, room: Number(value(f, 'room')), person: Number(value(f, 'person')), start: instantLocal(value(f, 'date'), value(f, 'time')), accepted: checked(f, 'accepted'), accepted_terms: { duration: s.external_duration, price: s.external_price, retention: s.retention } }; if (cat === 'student')
        body.student = Number(value(f, 'student')); await mutate('reserve', body); });
    modal.querySelector('#check-availability').addEventListener('click', async () => { const f = modal.querySelector('form'); const display = modal.querySelector('#availability-result'); display.textContent = 'Consultando o servidor…'; try {
        const result = await api('availability', { date: value(f, 'date'), category: value(f, 'category'), room: Number(value(f, 'room')), person: Number(value(f, 'person')), student: Number(value(f, 'student')) });
        display.innerHTML = result.slots.length ? result.slots.map((slot) => `<div class="activity"><b>${esc(slot.time)}</b> · ${slot.available ? 'Disponível' : esc(slot.reason)}</div>`).join('') : esc(result.reason || 'Sem oferta.');
    }
    catch (e) {
        display.textContent = e.message;
    } });
    const select = modal.querySelector('#book-category');
    const update = () => { const cat = select.value; modal.querySelector('#book-person').innerHTML = options(state.people.filter(p => cat === 'external' ? p.kind === 'external' : can('teacher', 'intern') ? p.id === session.user.person : p.kind === 'internal')); modal.querySelector('#student-field').hidden = cat !== 'student'; const amount = cat === 'external' ? s.external_price : 0; const refund = amount - Math.floor(amount * s.retention / 100); modal.querySelector('#booking-terms').innerHTML = cat === 'external' ? `<b>ATENÇÃO — POLÍTICA DE CANCELAMENTO E FALTA</b><br>Aluguel: <b>${money(amount)}</b> por ${s.external_duration} minutos. Cancelamento ou falta do profissional: retenção de ${s.retention}% (${money(amount - refund)}) e devolução manual de ${money(refund)}. Reserva temporária por ${s.hold_minutes} minutos. <b>Demonstração: não transfira dinheiro.</b>` : cat === 'student' ? `${s.student_duration} minutos · gratuito. Uma avaliação por CPF/mês. Marque na sexta para segunda a quinta da próxima semana. Falta/cancelamento do aluno consome o benefício.` : `${s.internal_duration} minutos · gratuito. Fora da própria jornada. Cancelamento impede novas reservas por ${s.penalty_hours}h. Prazo automático de confirmação de uso: ${s.use_deadline_minutes === null ? 'pendente de definição' : s.use_deadline_minutes + ' minutos após término'}.`; modal.querySelector('#accept-policy').innerHTML = cat === 'external' ? '<label class="check"><input name="accepted" type="checkbox" required>Informei ao profissional o valor, a duração e a política de cancelamento e falta, e ele concordou.</label>' : ''; };
    select.onchange = update;
    update();
}
function reservationDetail(id) {
    const r = state.reservations.find(r => r.id === id);
    const operational = can('admin', 'manager', 'reception') || [r.person, r.tutor].includes(session.user.person);
    const active = ['confirmed', 'no_show'].includes(r.status);
    dialog('Atendimento #' + id, `<div class="row">${badge(r.category)} ${badge(r.status)} ${r.payment ? badge(r.payment) : ''}</div><div class="detail-list" style="margin:24px 0"><div><span>Data / horário</span>${dateFormat(r.start, { weekday: 'long', day: '2-digit', month: '2-digit' })} · ${timeFormat(r.start)}–${timeFormat(r.end)}</div><div><span>Sala</span>${esc(room(r.room))}</div><div><span>Responsável</span>${esc(person(r.person)?.name)}</div><div><span>Aluno / profissional</span>${esc(person(r.student)?.name || person(r.person)?.name)}</div><div><span>CPF / telefone do aluno</span>${esc(cpff(person(r.student)?.cpf))} · ${esc(phonef(person(r.student)?.phone))}</div><div><span>Marcos</span>${r.whatsapp ? 'WhatsApp confirmado' : 'WhatsApp pendente'} · ${esc(r.presence)} · ${r.training ? 'Treino lançado' : 'Treino pendente'}</div></div><div class="notice">${r.terms.duration} minutos ${r.terms.price !== undefined ? ' · ' + money(r.terms.price) : ''}${r.payment === 'pending' ? '<br>Aguardando conferência no banco. QR Code externo não configurado na demonstração.' : ''}${r.relocated ? '<br>Vaga exclusiva · realocado por imprevisto. Histórico preservado na auditoria.' : ''}</div><div class="row">${can('admin', 'reception') && ['awaiting_payment', 'expired'].includes(r.status) ? '<button type="button" id="pay-open" class="primary">Conferir Pix manual</button>' : ''}${operational && active ? '<button type="button" data-ra="whatsapp">WhatsApp manual</button><button type="button" data-ra="presence">Compareceu</button>' : ''}${operational && active && can('admin', 'teacher') ? '<button type="button" data-ra="training">Treino lançado</button>' : ''}${operational && r.category !== 'student' && active ? '<button type="button" data-ra="use">Confirmar uso</button>' : ''}${can('reception') && r.presence === 'faltou' ? '<button type="button" id="justify-open">Justificar atraso</button>' : ''}${operational && ['confirmed', 'awaiting_payment'].includes(r.status) ? '<button type="button" class="danger" id="cancel-open">Cancelar reserva</button>' : ''}</div>`);
    modal.querySelectorAll('[data-ra]').forEach(b => b.onclick = async () => { try {
        await mutate('reservation-action', { id, action: b.dataset.ra });
        modal.close();
        await load();
    }
    catch (e) {
        toast(e.message, true);
    } });
    modal.querySelector('#pay-open')?.addEventListener('click', () => dialog('Conferência manual do Pix', `<div class="notice amber">Demonstração, sem transferência real. Valor devido: <b>${money(r.terms.price)}</b>. Em operação, conferir no banco antes de registrar. Não basta o comprovante.</div>${field('Valor conferido (centavos)', input('amount', 'number', String(r.terms.price), 'required min="0" step="1"'))}${field('Referência da transação (fictícia neste teste)', input('reference', 'text', '', 'required minlength="4"'))}<label class="check">${input('confirmed', 'checkbox', '', 'required')}Confirmei o recebimento (simulação local).</label>${actions('Registrar conferência')}`, async (f) => { await mutate('reservation-action', { id, action: 'pay', amount: Number(value(f, 'amount')), reference: value(f, 'reference') }); }));
    modal.querySelector('#cancel-open')?.addEventListener('click', () => { const retention = Math.floor((r.terms.price || 0) * (r.terms.retention || 0) / 100); dialog('Confirmar cancelamento', `<div class="notice amber">${r.category === 'external' ? `Sobre o pagamento original: retenção de ${money(retention)}, devolução de ${money((r.terms.price || 0) - retention)}. Se ainda não houve pagamento, nenhum reembolso é criado.` : r.category === 'student' ? 'Cancelamento do aluno mantém o benefício mensal comprometido. Se a causa foi imprevisto da academia, use o fluxo de bloqueio e realocação.' : 'Cancelamento do profissional gera impedimento de 48h para novas reservas.'}</div>${field('Motivo', input('reason', 'text', '', 'required'))}${can('admin', 'reception') && r.category !== 'student' ? '<label class="check"><input name="academy" type="checkbox">Cancelamento causado pela academia (sem penalidade; devolução integral se pago).</label>' : ''}${actions('Confirmar cancelamento')}`, async (f) => { await mutate('reservation-action', { id, action: 'cancel', reason: value(f, 'reason'), academy: checked(f, 'academy') }); }); });
    modal.querySelector('#justify-open')?.addEventListener('click', () => dialog('Justificar atraso real', `${field('Motivo ativo', `<select name="reason_id">${options(state.reasons.filter(r => r.active).map(r => ({ id: r.id, name: r.title })))}</select>`)}${field('Complemento', input('detail', 'text', '', 'required'))}${field('Presença efetiva (data e hora com fuso)', input('occurred', 'text', r.start, 'required'))}<label class="check"><input name="actually_attended" type="checkbox" required>O aluno efetivamente compareceu e foi atendido no intervalo original.</label>${actions('Corrigir presença sem liberar benefício')}`, async (f) => { await mutate('reservation-action', { id, action: 'justify', reason_id: Number(value(f, 'reason_id')), detail: value(f, 'detail'), occurred: value(f, 'occurred'), actually_attended: checked(f, 'actually_attended') }); }));
}
function personDialog() { dialog('Cadastrar pessoa', `<div class="form-grid">${field('Vínculo', `<select name="kind" id="person-kind">${(can('admin') ? ['student', 'external', 'internal', 'intern'] : ['student', 'external']).map(k => `<option value="${k}">${{ student: 'Aluno', external: 'Profissional externo', internal: 'Equipe interna', intern: 'Estagiário' }[k]}</option>`).join('')}</select>`)}${field('Nome e sobrenome', input('name', 'text', '', 'required'))}${field('Telefone com DDD', input('phone', 'tel', '', 'required'))}<div id="cpf-field">${field('CPF', input('cpf', 'text', '', 'inputmode="numeric"'))}</div><div id="profession-fields" class="field full"><div class="form-grid">${field('Profissão', `<select name="profession"><option value="pe">Personal / Profissional de Educação Física</option><option value="nutrition">Nutricionista</option></select>`)}${field('Número CREF / CRN', input('number'))}${field('Região / UF', input('region'))}</div></div><div id="tutor-field">${field('Tutor responsável', `<select name="tutor">${options(state.people.filter(p => p.kind === 'internal' && p.profession === 'pe'))}</select>`)}</div>${field('Matrícula / identificação', input('registration'))}${field('Vigência do plano', input('plan_until', 'date', '2099-12-31'))}</div><div class="notice" style="margin-top:20px">Somente dados fictícios. O preenchimento do conselho não representa verificação no órgão.</div>${actions('Salvar cadastro')}`, async (f) => { await mutate('people', { kind: value(f, 'kind'), name: value(f, 'name'), phone: value(f, 'phone'), cpf: value(f, 'cpf'), profession: value(f, 'profession'), number: value(f, 'number'), region: value(f, 'region'), tutor: Number(value(f, 'tutor')), registration: value(f, 'registration'), plan_until: value(f, 'plan_until') }); }); const select = modal.querySelector('#person-kind'); const update = () => { const kind = select.value; modal.querySelector('#cpf-field').hidden = !['student', 'intern'].includes(kind); modal.querySelector('#profession-fields').hidden = !['internal', 'external'].includes(kind); modal.querySelector('#tutor-field').hidden = kind !== 'intern'; }; select.onchange = update; update(); }
function blockDialog() { dialog('Bloquear por imprevisto', `<div class="form-grid">${field('Escopo', `<select name="scope"><option value="room">Sala indisponível</option><option value="person">Profissional indisponível</option></select>`)}${field('Sala', `<select name="room">${options(state.rooms)}</select>`)}${field('Profissional', `<select name="person">${options(state.people.filter(p => p.kind === 'internal'), session.user.person)}</select>`)}${field('Data', input('date', 'date', selectedDate, 'required'))}${field('Início', input('start', 'time', '08:00', 'required'))}${field('Fim', input('end', 'time', '11:00', 'required'))}${field('Motivo do bloqueio', '<textarea name="reason" required></textarea>', true)}</div><div class="notice" style="margin-top:15px">Se houver atendimentos, será necessário resolver cada um antes de concluir. Professor pode bloquear somente a própria disponibilidade.</div>${actions('Verificar e continuar')}`, async (f) => { const d = { start: instantLocal(value(f, 'date'), value(f, 'start')), end: instantLocal(value(f, 'date'), value(f, 'end')), reason: value(f, 'reason') }; d[value(f, 'scope')] = Number(value(f, value(f, 'scope'))); try {
    await mutate('block', d);
}
catch (e) {
    const err = e;
    if (!err.details?.affected)
        throw err;
    setTimeout(() => resolveDialog(d, err.details.affected), 0);
    throw new Error('Há atendimentos afetados. Abrindo as decisões individuais…');
} }); }
function resolveDialog(d, ids) { dialog('Resolver atendimentos afetados', `<div class="notice amber">${esc(d.reason)}. Manter retira o intervalo da avaliação do bloqueio. Realocar requer ciência do aluno e destino elegível; nenhuma alteração será parcial.</div>${ids.map(id => { const r = state.reservations.find(r => r.id === id); return `<div class="card"><div class="card-body"><h3>#${id} · ${esc(person(r.student)?.name || person(r.person)?.name)} · ${timeFormat(r.start)}</h3><div class="form-grid">${field('Decisão', `<select name="action-${id}"><option value="">Escolha</option><option value="keep">Manter avaliação</option>${r.category === 'student' ? '<option value="move">Realocar por imprevisto</option>' : ''}</select>`)}${field('Nova data (se realocar)', input('date-' + id, 'date', dayKey(r.start)))}${field('Novo início', input('time-' + id, 'time', timeFormat(r.start)))}${field('Sala de destino', `<select name="room-${id}">${options(state.rooms, r.room)}</select>`)}${field('Profissional de destino', `<select name="person-${id}">${options(state.people.filter(p => p.kind === 'internal'), r.person)}</select>`)}</div><label class="check" style="margin-top:15px"><input name="agreed-${id}" type="checkbox">Aluno concordou com a nova data/horário (se realocar).</label></div></div>`; }).join('')}${actions('Aplicar decisões e concluir bloqueio')}`, async (f) => { const decisions = {}; for (const id of ids) {
    decisions[id] = { action: value(f, 'action-' + id), start: instantLocal(value(f, 'date-' + id), value(f, 'time-' + id)), room: Number(value(f, 'room-' + id)), person: Number(value(f, 'person-' + id)), agreed: checked(f, 'agreed-' + id) };
} await mutate('block-resolve', { ...d, decisions }); }); }
function settingsDialog() { const s = state.unit.settings; dialog('Editar configuração versionada', `<div class="notice">Vigência e versão são verificadas no servidor. Uma mudança conflitante com reservas ou escalas publicadas será recusada.</div><div class="form-grid">${field('Vigência a partir de', input('effective_from', 'date', today(), 'required'))}${field('Oferta diária por sala', input('daily_offer', 'number', String(s.daily_offer), 'min="0" required'))}${['student', 'internal', 'external'].map(cat => field('Duração · ' + labels[cat], `<select name="${cat}_duration">${[20, 30, 40, 50, 60].map(v => `<option ${s[cat + '_duration'] === v ? 'selected' : ''}>${v}</option>`).join('')}</select>`)).join('')}${field('Preço externo em centavos', input('external_price', 'number', String(s.external_price), 'min="0" step="1" required'))}${field('Retenção (%)', input('retention', 'number', String(s.retention), 'min="0" max="100" required'))}${field('Validade da reserva Pix (min)', input('hold_minutes', 'number', String(s.hold_minutes), 'min="1" max="60" required'))}${field('Mês/ano inicial do ciclo', input('anchor', 'month', s.anchor.slice(0, 7), 'required'))}${field('Compartilhamento interno', `<select name="internal_sharing"><option value="shared" ${s.internal_sharing === 'shared' ? 'selected' : ''}>Quando livre</option><option value="exclusive" ${s.internal_sharing === 'exclusive' ? 'selected' : ''}>Exclusivo para alunos</option></select>`)}${field('Compartilhamento externo', `<select name="external_sharing"><option value="shared" ${s.external_sharing === 'shared' ? 'selected' : ''}>Quando livre</option><option value="exclusive" ${s.external_sharing === 'exclusive' ? 'selected' : ''}>Exclusivo para alunos</option></select>`)}</div><label class="check" style="margin-top:18px"><input name="external_weekdays" type="checkbox" ${s.external_weekdays ? 'checked' : ''}>Liberar dias úteis para externos</label><label class="check"><input name="anchor_confirmed" type="checkbox" ${s.anchor_confirmed ? 'checked' : ''}>Confirmo o primeiro dia do mês escolhido como âncora do ciclo de 84 dias.</label>${field('Configuração avançada (JSON): janelas, funcionamento, feriados e políticas pendentes', `<textarea name="advanced" class="mono-input">${esc(JSON.stringify({ windows: s.windows, opening: s.opening, holidays: s.holidays, use_deadline_minutes: s.use_deadline_minutes, professional_no_show_confirmed: s.professional_no_show_confirmed, supervision_confirmed: s.supervision_confirmed, intern_penalty_confirmed: s.intern_penalty_confirmed }, null, 2))}</textarea>`, true)}${actions('Validar impacto e salvar')}`, async (f) => { const settings = JSON.parse(value(f, 'advanced')); for (const k of ['daily_offer', 'student_duration', 'internal_duration', 'external_duration', 'external_price', 'retention', 'hold_minutes'])
    settings[k] = Number(value(f, k)); for (const k of ['external_weekdays', 'anchor_confirmed'])
    settings[k] = checked(f, k); settings.anchor = value(f, 'anchor') + '-01'; settings.effective_from = value(f, 'effective_from'); for (const k of ['internal_sharing', 'external_sharing'])
    settings[k] = value(f, k); await mutate('settings', { version: state.unit.version, settings }); }); }
function reasonDialog(id) { const r = state.reasons.find(r => r.id === id); dialog('Justificativa de atraso', `${field('Título', input('title', 'text', r?.title || '', 'required'))}<label class="check"><input name="active" type="checkbox" ${r?.active !== 0 ? 'checked' : ''}>Motivo ativo</label><label class="check"><input name="requires_detail" type="checkbox" ${r?.requires_detail !== 0 ? 'checked' : ''}>Exigir complemento</label>${actions()}`, async (f) => { await mutate('reason', { id, title: value(f, 'title'), active: checked(f, 'active'), requires_detail: checked(f, 'requires_detail') }); }); }
function workDialog() { dialog('Nova versão de jornada', `${field('Profissional', `<select name="person">${options(state.people.filter(p => ['internal', 'intern'].includes(p.kind)))}</select>`)}<div class="form-grid">${field('Início da vigência', input('valid_from', 'date', today(), 'required'))}${field('Fim da vigência', input('valid_to', 'date', '2027-12-31', 'required'))}${field('Carga contratual semanal (minutos)', input('contract_minutes', 'number', '2160', 'min="60" required'))}</div>${field('Dias e intervalos (JSON)', `<textarea name="days" class="mono-input">${esc(JSON.stringify([0, 1, 2, 3, 4].map(weekday => ({ weekday, start: '08:00', end: '14:00' })), null, 2))}</textarea>`)}<small>Dia 0 = segunda; 6 = domingo. Intervalos podem ser separados em mais de um registro por dia.</small>${actions('Validar e versionar jornada')}`, async (f) => { await mutate('work', { person: Number(value(f, 'person')), valid_from: value(f, 'valid_from'), valid_to: value(f, 'valid_to'), contract_minutes: Number(value(f, 'contract_minutes')), days: JSON.parse(value(f, 'days')) }); }); }
function editSchedule(id) { const sc = scheduleData.schedules.find((s) => s.id === id); dialog('Revisar rascunho #' + id, `<div class="notice amber">${sc.errors.length} pendências. Edite as alocações; o servidor revalida descanso, carga, cobertura e reservas. Para travar uma alocação na revisão, use <code>locked: true</code>; a gravação mantém sua escolha.</div>${sc.errors.length ? `<details><summary>Ver todas as pendências</summary><p class="description">${sc.errors.map(esc).join('<br>')}</p></details>` : ''}${field('Alocações (JSON)', `<textarea name="assignments" class="mono-input">${esc(JSON.stringify(sc.assignments.map((a) => { const { cycle, _index, ...rest } = a; return rest; }), null, 2))}</textarea>`)}${actions('Salvar e revalidar')}`, async (f) => { await mutate('schedule', { action: 'save', id, version: sc.version, assignments: JSON.parse(value(f, 'assignments')) }); }); }
function swapDialog() { const sc = scheduleData.schedules.find((s) => s.status === 'published'); if (!sc) {
    toast('Nenhuma escala publicada.', true);
    return;
} const my = sc.assignments.map((a, index) => ({ ...a, index: a._index ?? index })).filter((a) => a.person === session.user.person && !a.off && !a.adjustment); dialog('Solicitar permuta', `${field('Plantão de origem', `<select name="assignment">${options(my.map((a) => ({ id: a.index, name: `${dateFormat(a.date)} · ${a.slot} ${a.start}–${a.end}` })))}</select>`)}${field('Colega da mesma função', `<select name="target">${options(state.people.filter(p => p.kind === person(session.user.person)?.kind && p.id !== session.user.person))}</select>`)}${field('Motivo', input('reason', 'text', '', 'required'))}${actions('Enviar solicitação interna')}`, async (f) => { await mutate('swap', { action: 'request', schedule: sc.id, assignment: Number(value(f, 'assignment')), target: Number(value(f, 'target')), reason: value(f, 'reason') }); }); }
function bindPage() {
    const byId = (id, fn) => document.querySelector('#' + id)?.addEventListener('click', () => Promise.resolve(fn()).catch(e => toast(e.message + (e.details ? ' ' + JSON.stringify(e.details) : ''), true)));
    byId('add-person', personDialog);
    byId('add-user', userDialog);
    byId('add-room', () => dialog('Cadastrar sala', field('Nome da sala', input('name', 'text', '', 'required')) + actions(), async (f) => { await mutate('room', { name: value(f, 'name') }); }));
    byId('edit-settings', settingsDialog);
    byId('add-reason', () => reasonDialog());
    byId('add-work', workDialog);
    byId('request-swap', swapDialog);
    byId('generate-schedule', () => dialog('Gerar proposta do ciclo', field('Data de referência do ciclo', input('date', 'date', today(), 'required')) + '<div class="notice" style="margin-top:18px">O sistema gera os 84 dias do ciclo que contém esta data, preservando a âncora e verificando as fronteiras com versões publicadas.</div>' + actions('Gerar e validar ciclo'), async (f) => { toast('Gerando e validando o ciclo completo…'); await mutate('schedule', { action: 'generate', date: value(f, 'date') }); }));
    byId('view-day', () => { view = 'day'; render(); });
    byId('view-week', () => { view = 'week'; render(); });
    document.querySelector('#date-filter')?.addEventListener('change', e => { selectedDate = e.target.value; render(); });
    document.querySelector('#category-filter')?.addEventListener('change', e => { category = e.target.value; render(); });
    document.querySelector('#search-filter')?.addEventListener('change', e => { search = e.target.value; render(); });
    byId('export', async () => { const data = await api('export'); const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })); a.download = 'prisma-unidade-' + activeUnit + '.json'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000); });
    document.querySelectorAll('[data-reason]').forEach(b => b.onclick = () => reasonDialog(Number(b.dataset.reason)));
    document.querySelectorAll('[data-unblock]').forEach(b => b.onclick = async () => { try {
        await mutate('unblock', { id: Number(b.dataset.unblock) });
        await load();
    }
    catch (e) {
        toast(e.message, true);
    } });
    document.querySelectorAll('[data-audit]').forEach(b => b.onclick = () => { const a = state.audit.find(a => a.id === Number(b.dataset.audit)); dialog('Evento #' + a.id, `<pre class="code" style="white-space:pre-wrap">${esc(JSON.stringify(JSON.parse(a.data), null, 2))}</pre>`); });
    document.querySelectorAll('[data-edit-schedule]').forEach(b => b.onclick = () => editSchedule(Number(b.dataset.editSchedule)));
    document.querySelectorAll('[data-publish]').forEach(b => b.onclick = async () => { const sc = scheduleData.schedules.find((s) => s.id === Number(b.dataset.publish)); try {
        await mutate('schedule', { action: 'publish', id: sc.id, version: sc.version });
        await load();
    }
    catch (e) {
        toast(e.message, true);
    } });
    for (const action of ['accept', 'approve'])
        document.querySelectorAll('[data-swap-' + action + ']').forEach(b => b.onclick = async () => { try {
            await mutate('swap', { action, id: Number(b.getAttribute('data-swap-' + action)) });
            await load();
        }
        catch (e) {
            toast(e.message, true);
        } });
    document.querySelectorAll('[data-refund]').forEach(b => b.onclick = () => { const r = state.refunds.find(r => r.id === Number(b.dataset.refund)); dialog('Registrar devolução manual', `<div class="notice amber">Devolver ${money(r.amount)} fora do sistema. Durante os testes, use somente referência fictícia e não transfira dinheiro.</div>${field('Referência de devolução', input('reference', 'text', '', 'required'))}<label class="check"><input name="actually_refunded" type="checkbox" required>Confirmo a devolução efetiva (simulação no teste local).</label>${actions('Registrar devolução')}`, async (f) => { await mutate('refund', { id: r.id, amount: r.amount, reference: value(f, 'reference'), actually_refunded: checked(f, 'actually_refunded') }); }); });
    document.querySelector('#password-form')?.addEventListener('submit', async (e) => { e.preventDefault(); const f = e.currentTarget; try {
        await mutate('password', { current: value(f, 'current'), password: value(f, 'password'), confirmation: value(f, 'confirmation') });
        clearInterval(refreshTimer);
        state = undefined;
        await loginScreen();
    }
    catch (err) {
        f.querySelector('.inline-error').textContent = err.message;
    } });
}
async function start() { try {
    session = await api('session');
    activeUnit = session.user.unit;
    await load();
    refreshTimer = window.setInterval(() => { if (!modal.open && !document.activeElement?.matches('input,textarea,select') && page !== 'account')
        load(false).catch(() => { }); }, 15000);
}
catch {
    await loginScreen();
} }
start();
function userDialog() { dialog('Criar conta individual', `<div class="form-grid">${field('Nome de acesso', input('login', 'text', '', 'required'))}${field('Perfil', `<select name="role"><option value="manager">Gerência</option><option value="reception">Recepção</option><option value="teacher">Professor</option><option value="intern">Estagiário</option></select>`)}${field('Profissional (somente professor/estagiário)', `<select name="person">${options(state.people.filter(p => ['internal', 'intern'].includes(p.kind)))}</select>`)}${field('Senha inicial', input('password', 'password', '', 'minlength="10" required'))}</div><div class="notice" style="margin-top:20px">Conta restrita à unidade ativa. Externos e alunos não recebem acesso.</div>${actions('Criar conta')}`, async (f) => { await mutate('user', { login: value(f, 'login'), role: value(f, 'role'), person: Number(value(f, 'person')), password: value(f, 'password') }); }); }
